<?php require __DIR__.'/../config/config.php';$count=(int)$pdo->query('SELECT COUNT(*) FROM admin')->fetchColumn();if($count>0)exit('Admin already initialized. Delete this setup.php file.');$user='admin';$pass=bin2hex(random_bytes(6));$s=$pdo->prepare('INSERT INTO admin(username,password_hash) VALUES(?,?)');$s->execute([$user,password_hash($pass,PASSWORD_DEFAULT)]);echo 'Admin username: '.e($user).'<br>Temporary password: '.e($pass).'<br>Save it securely, sign in, then delete admin/setup.php.';